//! What a newer T3 Code sends, decoded by this build's types.
//!
//! `fixtures/newer-server/` holds the RPC and HTTP surface of a newer T3 (`manifest.json`) with
//! values generated by Effect's `Arbitrary` from *its* schemas (`samples/`), written by
//! `codegen/newer-server.sh`, plus values captured from a running newer server (`live/`). Each
//! value is decoded with the type this build generated for the same RPC tag or endpoint: a newer
//! server may add fields, enum values, union members and list elements, and none of them may
//! fail a decode.

use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
};

use serde::{Serialize, de::DeserializeOwned};
use serde_json::Value;

mod dispatch {
    use super::rt;
    include!("../src/generated/dispatch.rs");
}

fn rt<T: DeserializeOwned + Serialize>(v: Value) -> Result<Value, String> {
    let t: T = serde_json::from_value(v).map_err(|e| e.to_string())?;
    serde_json::to_value(&t).map_err(|e| e.to_string())
}

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn read_json(path: &Path) -> Value {
    let text = fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// The definition a manifest entry names, where it names one.
fn def(entry: &Value, key: &str) -> Option<String> {
    match &entry[key] {
        Value::String(def) => Some(def.clone()),
        Value::Object(reference) if reference.get("kind") == Some(&Value::from("ref")) => {
            reference["def"].as_str().map(str::to_string)
        }
        _ => None,
    }
}

/// This build's definitions for what a server sends, keyed by RPC tag or `METHOD path`:
/// (success, errors).
fn current_surface() -> BTreeMap<String, (Option<String>, Vec<String>)> {
    let manifest = read_json(&crate_dir().join("schema/manifest.json"));
    let mut surface = BTreeMap::new();
    for rpc in manifest["rpc"].as_array().unwrap() {
        let tag = rpc["tag"].as_str().unwrap().to_string();
        surface.insert(
            format!("rpc {tag}"),
            (def(rpc, "success"), def(rpc, "error").into_iter().collect()),
        );
    }
    for endpoint in manifest["http"].as_array().unwrap() {
        let key = format!(
            "http {} {}",
            endpoint["method"].as_str().unwrap(),
            endpoint["path"].as_str().unwrap()
        );
        let success = endpoint["success"]
            .as_array()
            .and_then(|responses| responses.first())
            .and_then(|response| def(response, "type"));
        let errors = endpoint["errors"]
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|response| def(response, "type"))
            .collect();
        surface.insert(key, (success, errors));
    }
    surface
}

/// What a newer T3 changed in ways that aren't additive, in calls mustr never makes, and why each
/// is accepted. Anything else that fails to decode fails the test.
const NOT_ADDITIVE: &[(&str, &str)] = &[
    (
        "http GET /.well-known/oauth-authorization-server",
        "0.1.4 nightlies serve MCP's OAuth metadata here, without the relay's required DPoP fields",
    ),
    (
        "http GET /.well-known/oauth-protected-resource",
        "0.1.4 nightlies serve MCP's OAuth metadata here, without the relay's required DPoP fields",
    ),
];

fn samples(dir: &Path, def: &str) -> Vec<Value> {
    let path = dir.join(format!("{def}.json"));
    if !path.exists() {
        return Vec::new();
    }
    match read_json(&path) {
        Value::Array(values) => values,
        value => vec![value],
    }
}

#[test]
fn a_newer_servers_values_decode() {
    let fixtures = crate_dir().join("tests/fixtures/newer-server");
    let source = read_json(&fixtures.join("SOURCE.json"));
    let newer = read_json(&fixtures.join("manifest.json"));
    let current = current_surface();
    let sample_dir = fixtures.join("samples");

    let (mut checked, mut values, mut skipped) = (0, 0, BTreeSet::new());
    let mut failures = BTreeMap::new();
    let mut accepted = BTreeSet::new();
    let mut decode = |key: &str, newer_def: &str, current_def: &str| {
        for (i, value) in samples(&sample_dir, newer_def).into_iter().enumerate() {
            values += 1;
            match dispatch::roundtrip(current_def, value) {
                Some(Ok(_)) => {}
                Some(Err(_)) if NOT_ADDITIVE.iter().any(|(known, _)| *known == key) => {
                    accepted.insert(key.to_string());
                }
                Some(Err(error)) => {
                    failures
                        .entry(format!("{key} ({newer_def} as {current_def})"))
                        .or_insert(format!("sample {i}: {error}"));
                }
                None => panic!("no Rust type for {current_def}"),
            }
        }
    };

    let entries = newer["rpc"]
        .as_array()
        .unwrap()
        .iter()
        .map(|rpc| (format!("rpc {}", rpc["tag"].as_str().unwrap()), rpc))
        .chain(newer["http"].as_array().unwrap().iter().map(|endpoint| {
            let key = format!(
                "http {} {}",
                endpoint["method"].as_str().unwrap(),
                endpoint["path"].as_str().unwrap()
            );
            (key, endpoint)
        }));
    for (key, entry) in entries {
        let Some((current_success, current_errors)) = current.get(&key) else {
            // Only a newer server has it, so this build never calls it.
            skipped.insert(key);
            continue;
        };
        checked += 1;
        if let (Some(newer_def), Some(current_def)) = (def(entry, "success"), current_success) {
            decode(&key, &newer_def, current_def);
        }
        let newer_errors: Vec<String> = match &entry["errors"] {
            Value::Array(errors) => errors
                .iter()
                .filter_map(|e| e.as_str().map(str::to_string))
                .collect(),
            _ => def(entry, "error").into_iter().collect(),
        };
        for newer_def in newer_errors {
            // An RPC has one error union; an endpoint's errors are matched by name.
            let current_def = if key.starts_with("rpc ") {
                current_errors.first()
            } else {
                current_errors.iter().find(|current| **current == newer_def)
            };
            if let Some(current_def) = current_def {
                decode(&key, &newer_def, current_def);
            }
        }
    }

    eprintln!(
        "T3 {}: {checked} RPCs and endpoints both builds have, {values} values, {} only in the newer one",
        source["t3Version"],
        skipped.len()
    );
    for (key, why) in NOT_ADDITIVE {
        if accepted.contains(*key) {
            eprintln!("  not additive, accepted: {key}: {why}");
        }
    }
    for (key, error) in &failures {
        eprintln!("  FAIL {key}: {error}");
    }
    assert!(values > 1000, "only {values} values: is the corpus there?");
    assert!(
        failures.is_empty(),
        "{} RPCs or endpoints of T3 {} don't decode",
        failures.len(),
        source["t3Version"]
    );
}

/// `live/<Def>.<label>.json`: what a running newer server sent (an array of values, such as a
/// stream's items), as the type this build generated for `<Def>`.
#[test]
fn a_newer_servers_live_payloads_decode() {
    let dir = crate_dir().join("tests/fixtures/newer-server/live");
    let mut files: Vec<_> = fs::read_dir(&dir)
        .map(|entries| entries.map(|e| e.unwrap().path()).collect())
        .unwrap_or_default();
    files.retain(|path| path.extension().is_some_and(|ext| ext == "json"));
    files.sort();
    let mut failures = Vec::new();
    for path in &files {
        let name = path.file_name().unwrap().to_str().unwrap();
        let def = name.split('.').next().unwrap();
        let Value::Array(values) = read_json(path) else {
            panic!("{name} isn't an array of values");
        };
        for (i, value) in values.into_iter().enumerate() {
            match dispatch::roundtrip(def, value) {
                Some(Ok(_)) => {}
                Some(Err(error)) => failures.push(format!("{name}[{i}]: {error}")),
                None => failures.push(format!("{name}: no Rust type for {def}")),
            }
        }
    }
    eprintln!("{} live payloads", files.len());
    assert!(failures.is_empty(), "{failures:#?}");
}

/// RPCs and endpoints mustr calls that the newer T3 dropped, and how mustr does without them.
/// Anything else mustr calls must still be there.
const DROPPED_WITH_FALLBACK: &[(&str, &str)] = &[(
    "rpc server.getSettings",
    "the new-thread form reads the settings from server.getConfig (thread_chat/src/new_thread.rs)",
)];

/// `rpc::X` and `http::X` in `methods.rs`: struct name -> `rpc <tag>` or `http <METHOD> <path>`.
fn method_table() -> BTreeMap<String, String> {
    let methods = fs::read_to_string(crate_dir().join("src/generated/methods.rs")).unwrap();
    let constant = |line: &str, name: &str| {
        line.trim()
            .strip_prefix(&format!("const {name}: &'static str = \""))
            .and_then(|rest| rest.strip_suffix("\";"))
            .map(str::to_string)
    };
    let mut table = BTreeMap::new();
    let lines: Vec<&str> = methods.lines().collect();
    for (i, line) in lines.iter().enumerate() {
        let Some(name) = line
            .trim()
            .strip_prefix("pub struct ")
            .and_then(|rest| rest.strip_suffix(';'))
        else {
            continue;
        };
        let body = &lines[i + 1..(i + 5).min(lines.len())];
        if let Some(tag) = body.iter().find_map(|line| constant(line, "TAG")) {
            table.insert(name.to_string(), format!("rpc {tag}"));
        } else if let (Some(method), Some(path)) = (
            body.iter().find_map(|line| constant(line, "METHOD")),
            body.iter().find_map(|line| constant(line, "PATH")),
        ) {
            table.insert(name.to_string(), format!("http {method} {path}"));
        }
    }
    table
}

/// Every `rpc::X` and `http::X` the code of `dir` names, outside its tests.
fn calls_in(dir: &Path, table: &BTreeMap<String, String>, calls: &mut BTreeMap<String, String>) {
    for entry in fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        if path.is_dir() {
            if name != "tests" && name != "generated" {
                calls_in(&path, table, calls);
            }
            continue;
        }
        if !name.ends_with(".rs") || name.ends_with("tests.rs") || name == "test_rpc.rs" {
            continue;
        }
        let text = fs::read_to_string(&path).unwrap();
        for prefix in ["rpc::", "http::"] {
            for (at, _) in text.match_indices(prefix) {
                let ident: String = text[at + prefix.len()..]
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                    .collect();
                if let Some(call) = table.get(&ident) {
                    let file = path
                        .strip_prefix(crate_dir().parent().unwrap())
                        .unwrap_or(&path);
                    calls
                        .entry(call.clone())
                        .or_insert_with(|| file.display().to_string());
                }
            }
        }
    }
}

#[test]
fn a_newer_server_has_every_call_mustr_makes() {
    let fixtures = crate_dir().join("tests/fixtures/newer-server");
    let source = read_json(&fixtures.join("SOURCE.json"));
    let newer = read_json(&fixtures.join("manifest.json"));
    let mut available = BTreeSet::new();
    for rpc in newer["rpc"].as_array().unwrap() {
        available.insert(format!("rpc {}", rpc["tag"].as_str().unwrap()));
    }
    for endpoint in newer["http"].as_array().unwrap() {
        available.insert(format!(
            "http {} {}",
            endpoint["method"].as_str().unwrap(),
            endpoint["path"].as_str().unwrap()
        ));
    }

    let table = method_table();
    let mut calls = BTreeMap::new();
    let crates = crate_dir().parent().unwrap().to_path_buf();
    for name in ["t3_client", "thread_chat", "mustr", "review"] {
        let src = crates.join(name).join("src");
        if src.is_dir() {
            calls_in(&src, &table, &mut calls);
        }
    }
    assert!(
        calls.len() > 40,
        "only found {} calls: {calls:#?}",
        calls.len()
    );

    let mut missing = Vec::new();
    for (call, file) in &calls {
        if available.contains(call) {
            continue;
        }
        match DROPPED_WITH_FALLBACK
            .iter()
            .find(|(dropped, _)| dropped == call)
        {
            Some((_, fallback)) => eprintln!("  dropped, with a fallback: {call}: {fallback}"),
            None => missing.push(format!("{call} (called in {file})")),
        }
    }
    eprintln!(
        "T3 {}: has {} of the {} calls mustr makes",
        source["t3Version"],
        calls
            .keys()
            .filter(|call| available.contains(*call))
            .count(),
        calls.len()
    );
    assert!(
        missing.is_empty(),
        "T3 {} no longer has calls mustr makes: {missing:#?}",
        source["t3Version"]
    );
}
